import vocab from "./vocab.json";
import type { Topic, TopicSummary, Word } from "./types";

// Generated by scripts/build_vocab.py from the shared Google Drive folder
export const SOURCE_URL = vocab.source;
export const topics = vocab.topics as Topic[];

export function topicSummaries(): TopicSummary[] {
  return topics.map((t) => ({
    slug: t.slug,
    name: t.name,
    count: t.words.length,
    ids: t.words.map((w) => w.id),
  }));
}

export function getTopic(slug: string) {
  return topics.find((t) => t.slug === slug);
}

function fold(s: string) {
  return s
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/đ/g, "d");
}

// match whole Vietnamese syllables, so "chó" doesn't match "nhanh chóng"
function hasPhrase(text: string, phrase: string) {
  return ` ${text.replace(/[^\p{L}\p{N}]+/gu, " ")} `.includes(` ${phrase} `);
}

export function searchWords(q: string, limit = 50) {
  const raw = q.trim().toLowerCase().normalize("NFC");
  // only ignore accents when the query has none ("tao" finds "táo", "táo" doesn't find "tạo")
  const accentless = fold(raw) === raw.replace(/đ/g, "d");
  const norm = (s: string) => (accentless ? fold(s) : s.toLowerCase().normalize("NFC"));
  const needle = norm(raw);
  if (!needle) return [];
  // "quả táo" should still find "Táo"
  const bare = needle.replace(/^(qua|quả|trai|trái|con|cai|cái|chiec|chiếc|cay|cây|nguoi|người|mon|món|bong|bông) /, "");
  const hits: (Word & { topic: string; topicSlug: string; score: number })[] = [];
  for (const t of topics) {
    for (const w of t.words) {
      const en = w.w.toLowerCase();
      const vi = norm(w.vi);
      let score = -1;
      if (en === needle) score = 0;
      else if (en.startsWith(needle)) score = 1;
      else if (vi.split(/[,;]\s*/).some((m) => m === needle || m === bare)) score = 2;
      else if (en.includes(needle)) score = 3;
      else if (hasPhrase(vi, needle)) score = 4;
      else if (bare !== needle && hasPhrase(vi, bare)) score = 5;
      if (score >= 0) hits.push({ ...w, topic: t.name, topicSlug: t.slug, score });
    }
  }
  return hits.sort((a, b) => a.score - b.score || a.w.length - b.w.length).slice(0, limit);
}
